entries[441410] = { ["name"] = "Schredderstich", ["text"] = "100 Meter Reichweite\nWirken in 1.5 sek.\nDie Glutbiene fällt einen Gegner an und sticht mit ihrem Stachel zu. Die Stichwunde verursacht 10 Sek. lang alle 2 Sek. 727335 körperlichen Blutungsschaden. Dieser Effekt ist stapelbar." }
