entries[441413] = { ["name"] = "Schredderstich", ["text"] = "8 Meter Reichweite\nSofort\nDie Glutbiene fällt einen Gegner an und sticht mit ihrem Stachel zu. Die Stichwunde verursacht 10 Sek. lang alle 2 Sek. 727335 körperlichen Blutungsschaden. Dieser Effekt ist stapelbar." }
entries[441414] = { ["name"] = "Wildes Wachstum", ["text"] = "100 Meter Reichweite\nSofort\nSetzt ansteckende Sporen frei, die Naturschaden verursachen und Schotlinge sowie ein Gebiet mit Dickicht entstehen lassen. Die Bewegungsgeschwindigkeit von Gegnern im Dickichtgebiet wird um 40% verringert, während sie alle 0.5 Sek. Naturschaden erleiden." }
entries[441415] = { ["name"] = "Nicht so misstrauisch", ["text"] = "Abklingzeit von 'Blenden' und 'Verhüllender Nebel' um 10% verringert.\n\nReichweite von 'Taschendiebstahl' und 'Kopfnuss' auf 10 Meter vergrößert." }
entries[441416] = { ["name"] = "Exterminieren", ["text"] = "Sofort\nFrost\nNachdem 'Mal des Schnitters' explodiert, kosten Eure nächsten [Quellwert] Einsätze von 1 [Quellwert]:Runen;; und beschwört 2 Sensen, die Eure Gegner trifft:treffen;.\n\nDie erste Sense fügt Eurem Ziel (407.975% der Angriffskraft) Schattenfrostschaden zu und hat eine Chance von 100%, eine 'Tötungsmaschine' zu gewähren. Die zweite Sense fügt allen Gegnern um Euer Ziel für (178.723% der Angriffskraft) Schattenfrostschaden zu [und belegt sie mit 'Frostfieber']. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nBlut\nNachdem 'Mal des Schnitters' explodiert, kosten Eure nächsten [Quellwert] Einsätze von 1 [Quellwert]:Runen;; und beschwört 2 Sensen, die Eure Gegner trifft:treffen;.\n\nDie erste Sense fügt Eurem Ziel (349.069% der Angriffskraft) Schattenfrostschaden zu und hat eine Chance von 100%, lang 2.0 Sek. einen 'Knochensturm' zu ernten. Die zweite Sense fügt allen Gegnern um Euer Ziel für (186.17% der Angriffskraft) Schattenfrostschaden zu [und belegt sie mit 'Frostfieber']. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n(1s Abklingzeit)", ["unresolvedValues"] = true }
entries[441417] = { ["name"] = "Wildes Wachstum", ["text"] = "100 Meter Reichweite\nSofort\nSetzt ansteckende Sporen frei, die Naturschaden verursachen und Schotlinge sowie ein Gebiet mit Dickicht entstehen lassen. Die Bewegungsgeschwindigkeit von Gegnern im Dickichtgebiet wird um 40% verringert, während sie alle 0.5 Sek. Naturschaden erleiden." }
