entries[441423] = { ["name"] = "Gnadenstoß", ["text"] = "Täuschung\nNach 4 Treffern mit 'Ungesehene Klinge' wird Euer nächster Einsatz von 'Ausweiden' als 'Gnadenstoß' ausgeführt, wodurch er so gewertet wird, als hätte er 5 zusätzliche Combopunkte verbraucht.\n\nWenn das Primärziel 'Entmutigt' ist, gewinnt Ihr 5 Stapel von 'Makellose Gestalt' hinzu.\n\nGesetzlosigkeit\nNach 4 Treffern mit 'Ungesehene Klinge' wird Euer nächster Einsatz von 'Tötung' als 'Gnadenstoß' ausgeführt, wodurch er so gewertet wird, als hätte er 5 zusätzliche Combopunkte verbraucht.\n\nWenn das Primärziel 'Entmutigt' ist, gewinnt Ihr 5 Stapel von 'Makellose Gestalt' hinzu." }
