entries[441583] = { ["name"] = "Verheeren", ["text"] = "Wildheit\nEure automatischen Angriffe haben eine Chance, Euren nächsten Einsatz von 'Wilder Biss' zu 'Verheeren' zu machen.\n\n$?a137010[ Verheeren\nDurchschlitzt Euer Ziel in einem weiten Bogen. Fügt dem Ziel (198.15% der Angriffskraft) körperlichen Schaden zu und allen anderen Gegnern vor Euch (74.07% der Angriffskraft) körperlichen Schaden. ]$?a137011[ Verheeren\nFinishing-Move, der in einem weiten Bogen durch Euer Ziel schlitzt. Fügt Eurem Ziel pro Combopunkt körperlichen Schaden zu und verbraucht bis zu 25 zusätzliche Energie, um diesen Schaden um bis zu 100% zu erhöhen. Trifft alle anderen Gegner vor Euch für weniger Schaden pro verbrauchtem Combopunkt.\n\n1 Punkt: [(257.78% der Angriffskraft) / 5] Schaden, [(93.84% der Angriffskraft) / 5] in einem Bogen\n2 Punkte: [(257.78% der Angriffskraft) * 2 / 5] Schaden, [(93.84% der Angriffskraft) * 2 / 5] in einem Bogen\n3 Punkte: [(257.78% der Angriffskraft) * 3 / 5] Schaden, [(93.84% der Angriffskraft) * 3 / 5] in einem Bogen\n4 Punkte: [(257.78% der Angriffskraft) * 4 / 5] Schaden, [(93.84% der Angriffskraft) * 4 / 5] in einem Bogen\n5 Punkte: [(257.78% der Angriffskraft) * 5 / 5] Schaden, [(93.84% der Angriffskraft) * 5 / 5] in einem Bogen ]\nWächter\nEure automatischen Angriffe haben eine Chance, Euren nächsten Einsatz von 'Zermalmen' zu 'Verheeren' zu machen.\n\n$?a137010[ Verheeren\nDurchschlitzt Euer Ziel in einem weiten Bogen. Fügt dem Ziel (198.15% der Angriffskraft) körperlichen Schaden zu und allen anderen Gegnern vor Euch (74.07% der Angriffskraft) körperlichen Schaden. ]$?a137011[ Verheeren\nFinishing-Move, der in einem weiten Bogen durch Euer Ziel schlitzt. Fügt Eurem Ziel pro Combopunkt körperlichen Schaden zu und verbraucht bis zu 25 zusätzliche Energie, um diesen Schaden um bis zu 100% zu erhöhen. Trifft alle anderen Gegner vor Euch für weniger Schaden pro verbrauchtem Combopunkt.\n\n1 Punkt: [(257.78% der Angriffskraft) / 5] Schaden, [(93.84% der Angriffskraft) / 5] in einem Bogen\n2 Punkte: [(257.78% der Angriffskraft) * 2 / 5] Schaden, [(93.84% der Angriffskraft) * 2 / 5] in einem Bogen\n3 Punkte: [(257.78% der Angriffskraft) * 3 / 5] Schaden, [(93.84% der Angriffskraft) * 3 / 5] in einem Bogen\n4 Punkte: [(257.78% der Angriffskraft) * 4 / 5] Schaden, [(93.84% der Angriffskraft) * 4 / 5] in einem Bogen\n5 Punkte: [(257.78% der Angriffskraft) * 5 / 5] Schaden, [(93.84% der Angriffskraft) * 5 / 5] in einem Bogen ]", ["unresolvedValues"] = true }
