entries[441689] = { ["name"] = "Ermächtigter Gestaltwandel", ["text"] = "'Rasende Regeneration' kann für 40 Energie in Katzengestalt gezaubert werden.\n\nIn Bärengestalt erleidet Ihr 6% weniger Magieschaden.\n\nDer Schaden von 'Schreddern' und [ Brutales Schlitzen : 'Brutales Schlitzen' / 'Prankenhieb'] ist um 6% erhöht und der Schaden von 'Zerfleischen' ist um 25% erhöht." }
