entries[441824] = { ["name"] = "Todesstöße", ["text"] = "Wildheit\n'Verheeren' erhöht Eure Beweglichkeit 8 Sek. lang um 8% und die durch 'Eisenfell' gewährte Rüstung um 20%.\n\nEuer erster Einsatz von 'Tigerfuror' nach Kampfbeginn lässt Euren nächsten Einsatz von 'Wilder Biss' zu 'Verheeren' werden.\n\nWächter\n'Verheeren' erhöht Eure Beweglichkeit 8 Sek. lang um 8% und die durch 'Eisenfell' gewährte Rüstung um 20%.\n\nEuer erster Einsatz von 'Zerfleischen' nach Kampfbeginn lässt Euren nächsten Einsatz von 'Zermalmen' zu 'Verheeren' werden." }
