entries[442037] = { ["name"] = "Spinndrüsenstränge", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan beschießt anvisierte Spielercharaktere mit Netzen, die Spielercharakteren innerhalb von 10 Metern 719539 Schattenschaden zufügen, das ursprüngliche Ziel fesseln und ' Klebrige Netze ' erschaffen.\n\nDie Verbindung verursacht alle 1 Sek. 172689 Schattenschaden und zieht das ursprüngliche Ziel zu sich. Wenn man sich 0 Meter bewegt, reißt die Verbindung, was einen ' Spinndrüsengespinstriss ' auslöst." }
entries[442038] = { ["name"] = "Spinndrüsenstränge", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan beschießt markierte Ziele mit Netzen, die Spielercharakteren innerhalb von 0 Metern 2014711 Naturschaden zufügen, alle getroffenen Spielercharaktere fesseln und ' Klebrige Netze ' erschaffen. Die Fessel verursacht alle 1 Sek. 575632 Naturschaden und zieht Opfer nach innen.\n\nWenn die Fessel 0 Meter gedehnt wird, reißt sie und löst einen ' Spinndrüsengespinstriss ' aus." }
