entries[442300] = { ["name"] = "Verzweifelt", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde weist Gegner innerhalb von 12 Metern mit Leerenenergie zurecht und fügt ihnen 40 Schattenschaden zu. Der verursachte Schaden getroffener Gegner wird 10 Sek. lang um 30% verringert und ihre hervorgerufene Heilung um 15%." }
entries[442303] = { ["name"] = "Gewebter Kokon", ["text"] = "Kanalisiert (Wirken in 6 sek.)\nWebt das Ziel in einen Kokon ein.\n\nWenn Ihr selbst das Ziel seid, verschwindet Ihr aus dem Kampf und heilt Euch 6 Sek. lang alle 1 Sek. um 15 Gesundheit. Wenn Ihr wieder auftaucht, seid Ihr in Netze gehüllt, die die nächsten 3 Gegner, die Nahkampfangriffe gegen Euch ausführen, 5 Sek. lang bewegungsunfähig machen.\n\nWenn Euer Ziel ein Gegner ist, wird er betäubt und erleidet 5 Sek. lang alle 1 Sek. 4 Naturschaden." }
entries[442304] = { ["name"] = "Einspinnen", ["text"] = "Sofort\nWebt das Ziel in einen Kokon ein.\n\nWenn Ihr selbst das Ziel seid, verschwindet Ihr aus dem Kampf und heilt Euch 6 Sek. lang alle 1 Sek. um 15 Gesundheit. Wenn Ihr wieder auftaucht, seid Ihr in Netze gehüllt, die die nächsten 3 Gegner, die Nahkampfangriffe gegen Euch ausführen, 5 Sek. lang bewegungsunfähig machen.\n\nWenn Euer Ziel ein Gegner ist, wird er betäubt und erleidet 5 Sek. lang alle 1 Sek. 4 Naturschaden." }
