entries[442428] = { ["name"] = "Dezimieren", ["text"] = "300 Meter Reichweite\nWirken in 2 sek.\nSikran entfesselt mit seiner Stangenwaffe ein Sperrfeuer aus kosmischen Eruptionen, die allen Spielercharakteren zwischen ihm und seinen Zielen 1439079 Schattenschaden zufügen.\n\nVon dem Effekt betroffene kosmische Simulakren werden zerstört." }
entries[442429] = { ["name"] = "Lauffeuerdocht", ["text"] = "Ca. 6 Procs pro Minute\nEure Nahkampfangriffe haben eine Chance, das Ziel in Brand zu stecken und ihm so ( 53 * 11) Feuerschaden im Verlauf von 11 Sek. zuzufügen.\n\nWenn dieser Effekt ausgelöst wird, während das Ziel bereits brennt, wird seine Dauer erneuert und er breitet sich auf einen Gegner in der Nähe aus." }
entries[442430] = { ["name"] = "Schwarzblut einnehmen", ["text"] = "100 Energie Unbegrenzte Reichweite\nSofort\nWenn Brutverderber Ovi'nax seine volle Energie erreicht hat, stürzt er sich auf einen vollen Kanister Schwarzblut und beginnt, ihn zu verschlingen. Durch das Verschlingen des Kanisters entfesselt er alle 5 Sek. einen Schwall von ' Widerwärtige Entladung ' und verursacht 1439079 Schattenschaden, der bei allen Spielercharakteren die nächsten 2453672 Heilung absorbiert. Wenn der Kanister leer ist, erhält Brutverderber Ovi'nax ' Instabile Infusion '." }
entries[442431] = { ["name"] = "Kauernd" }
entries[442432] = { ["name"] = "Schwarzblut einnehmen", ["text"] = "Unbegrenzte Reichweite\nWirken in 1 sek.\nWenn Brutverderber Ovi'nax volle Energie erreicht, bewegt er sich zum nächsten Schwarzblutbehälter zum ' Schwarzblut einnehmen ', wodurch er vom schwarzen Blut ermächtigt wird." }
