entries[442445] = { ["name"] = "Sturmarchon", ["text"] = "Sofort 18 sek. Abklingzeit\n- Linien-Wirkungsbereich\n- Erneut aktivierbar\n- Mehrfach wirkbar\n\n18 Sek. Abklingzeit\nRuft die Elemente herbei und entfesselt ein zerstörerisches Sperrfeuer vor dem Zaubernden.\n\nWirkt 'Sturmarchon' erneut, um ein anderes Element zu rufen. Kann zwei Mal erneut gewirkt werden." }
