entries[442489] = { ["name"] = "Schutzfäden", ["text"] = "Sofort\nBeim Erleiden von Magieschaden besteht eine Chance, dass die Spinnweben reagieren und sich anpassen, wodurch sie Euch für 30 Sek. Sek. mit Schutzfäden einwickeln. Solange die Schutzfäden aktiv sind, absorbieren sie sämtlichen Schaden, den Ihr durch Zauber dieser Quelle erleiden würdet, bis zu 9176 Schaden. (2 Min. Abklingzeit)" }
