entries[442493] = { ["name"] = "Grimmwebenkäfig", ["text"] = "45 Meter Reichweite\nSofort\nDer Zaubernde webt Runen aus Spinnweben und beschwört einen Käfig um sein Ziel. Der Käfig fügt dem Ziel pro Sekunde Schattenschaden zu, solange es darin gefangen ist. Wenn die Beute verfrüht flieht, birst der Käfig, fügt dem Ziel schweren Naturschaden zu und verlangsamt es 2.5 Sek. lang um 70." }
