entries[442495] = { ["name"] = "Finsternis", ["text"] = "Unbegrenzte Reichweite\nSofort\nKy'veza verschleiert Teile des Raums mit Wellen der Dunkelheit und fügt jedem Spielercharakter im Wirkungsbereich 8634473 Schattenschaden zu." }
entries[442497] = { ["name"] = "Erbitterter Angriff", ["text"] = "'Häschergleve' generiert 20 Zorn." }
entries[442498] = { ["name"] = "Finsteres Verderben", ["text"] = "Unbegrenzte Reichweite\nSofort\nDämonologie, Zerstörung\nDer durch 'Feuerbrand' verursachte regelmäßige Schaden hat die Chance, dem Ziel über 15 Sek. (46.9878% der Zaubermacht) Schattenflammenschaden zuzufügen.\n\nSchaden durch 'Chaosblitz' verbraucht 'Verdunkelnde Seele' und verursacht den übrigen Schaden sofort. Schaden, der durch 'Feuerregen' verursacht wird, verbraucht 1 Sek. von 'Verdunkelnde Seele'.\n\nGebrechen\nDer durch 'Verderbnis' verursachte regelmäßige Schaden hat die Chance, dem Ziel über 15 Sek. (46.9878% der Zaubermacht) Schattenflammenschaden zuzufügen.\n\nSchaden durch 'Unheilvolle Euphorie' verbraucht 'Verdunkelnde Seele' und verursacht den übrigen Schaden sofort." }
