entries[442566] = { ["name"] = "Düsternischitin", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nAuf Khaz Algar gibt es viele verschiedene Insekten, deren Exoskelette aus Chitin sich hervorragend und besser als Schuppen für die Herstellung robuster Kettenrüstung eignen." }
entries[442567] = { ["name"] = "Sturmgeladenes Leder", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nAuf Khaz Algar trifft man auf eine ganze Schar verschiedenster Kreaturen. Das von ihnen gewonnene Leder kann zur Herstellung einer Vielzahl von Waren, Rüstung und anderen Reagenzien eingesetzt werden." }
entries[442569] = { ["name"] = "Sonnenloser Panzer", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nKürschner haben beim Häuten von Chitinkreaturen eine geringe Chance, herausragende sonnenlose Panzer zu bekommen.\n\nDiese Panzer sind sehr robust und bestehen komplett aus Chitin, wodurch sie für die herausforderndsten Teile eingesetzt werden können." }
entries[442572] = { ["name"] = "Donnernde Haut", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nKürschner haben beim Sammeln ledriger Häute eine geringe Chance, außergewöhnliche donnernde Häute zu finden.\n\nDabei handelt es sich um ein enorm seltenes Material, das für viele Berufe zu gebrauchen ist." }
entries[442573] = { ["name"] = "Meucheln", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Astrale markiert mehrere Spielercharaktere als Ziele zum Meucheln. Nach 8 Sek. macht er rasch einen Schattenschritt zu jedem Ziel und weidet es aus, was innerhalb von 5 Metern 4605052 Schattenschaden verursacht und 'Königinnenmord' injiziert.\n\nDie schattenhafte Gestalt des Astralen hallt nach und erschafft ein ' Netherphantom ' an jeder Position." }
entries[442574] = { ["name"] = "Light Trigger - Medium", ["text"] = "300 Meter Reichweite\nSofort\nDas Licht geht von Euch aus und offenbart alle durch schattige Dunkelheit verborgenen Kreaturen.\n\nSolange das Licht scheint, könnt Ihr nicht in Verstohlenheit übergehen." }
