entries[442577] = { ["name"] = "Lauernde Dunkelheit", ["text"] = "Wirken in 1 sek.\nEin düsteres Ritual schleudert 6 Sek. lang Schattenblitze auf zufällige Gegner, die alle 0.5 Sek. 3 Schattenschaden verursachen." }
