entries[442602] = { ["name"] = "Herrschendes Siegel", ["text"] = "Wirken in 2.5 sek.\nDer Zaubernde ruft seine Mächte als Aufgestiegener an. Fügt allen Gegnern innerhalb von 10 Metern 16 Schattenschaden zu und knebelt sie mit einem Netz, um sie 4 Sek. lang zum Schweigen zu bringen." }
