entries[442604] = { ["name"] = "Blutspritzer", ["text"] = "300 Meter Reichweite\nSofort\nDer blutgebundene Schrecken entzieht Lachen in der Umgebung Schwarzblut und verleiht sich damit ' Sickernde Transfusion '. Dann entfesselt er eine Flutwelle aus Schwarzblut, die sich über alle Spielercharaktere innerhalb von 60 Metern ergießt und 20147103 Schattenschaden verursacht.\n\nRückstände bleiben an den verbleibenden Spielercharakteren haften und verursachen 10 Sek. lang alle 1 Sek. 518068 Schattenschaden." }
