entries[442615] = { ["name"] = "Fleisch schneiden", ["text"] = "Wirken in 3 sek. 1 Stunde Abklingzeit\n1 Aufladung\nMacht Euch fürs Schlachten bereit. Solange der Effekt aktiv ist, bekommt Ihr bei Eurem nächsten Kürschnervorgang garantiert Fleisch, das Ihr zum Kochen verwenden könnt." }
entries[442618] = { ["name"] = "Pheromone aufdecken", ["text"] = "18 Meter Reichweite\nWirken in 2 sek.\nUnterbricht die Wirkung der Pheromone und entlarvt Euch gegenüber den Nerubern!" }
entries[442621] = { ["name"] = "Toxische Absonderung", ["text"] = "20 Meter Reichweite\nSofort\nDer Zaubernde verströmt Gift aus seinem Körper, wodurch seine Treffer 5 Sek. lang alle 1 Sek. Naturschaden verursachen und die Bewegungsgeschwindigkeit um 7% verringern.\n\nDieser Effekt ist stapelbar." }
entries[442624] = { ["name"] = "Mal des Reißers", ["text"] = "Nahkampfreichweite\nSofort\nVerwüstung\nWenn 'Chaosstoß' durch 'Gleve des Reißers' verstärkt wird, wird 'Mal des Reißers' angewandt, wodurch das Ziel 20 Sek. lang 7% mehr Schaden erleidet. Bis zu 2-mal stapelbar.\n\nGewährt 1 zusätzlichen Stapel von 'Mal des Reißers', wenn es nach 'Klingentanz' eingesetzt wird.\n\nRachsucht\nWenn durch 'Gleve des Reißers' verstärkt wird, wird 'Mal des Reißers' angewandt, wodurch das Ziel 20 Sek. lang 7% mehr Schaden erleidet. Bis zu 2-mal stapelbar.\n\nGewährt 1 zusätzlichen Stapel von 'Mal des Reißers', wenn es nach 'Seelenspalter' eingesetzt wird.\n(100ms Abklingzeit)" }
