entries[442631] = { ["name"] = "Sprühender Blutsturz", ["text"] = "Sofort\nDer blutgebundene Schrecken erschafft auf jeder Seite zwei Geysire aus Schwarzblut, die sich 20 Sek. lang langsam um sich selbst drehen. Wer in einem Geysir steht, erleidet alle 0.25 Sek. 17268946 Schattenschaden." }
entries[442632] = { ["name"] = "Surekische Fesseln", ["text"] = "100 Meter Reichweite\nSofort\nSikran bindet Spielercharaktere aneinander und fügt ihnen alle 1 Sek. 8 Schattenschaden zu. Die Verbindung reißt, wenn sich die Spielercharaktere 20 Meter voneinander entfernen." }
