entries[442636] = { ["name"] = "Frostblitz", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nDer Zaubernde verschießt einen Eisblitz auf sein aktuelles Ziel, der diesem Frostschaden zufügt und es 5 Sek. lang um 75 verlangsamt." }
