entries[442644] = { ["name"] = "Köder für Spiegelregenbogenfische", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTrödelnder Häsling (2)\nSpezialisierung:\nAbbauen - Fischereifreund\n\nKöder für Spiegelregenbogenfische\nBenutzen: Erhöht 30 Min. lang die Chance, Spiegelregenbogenfische zu fangen.\n70" }
entries[442645] = { ["name"] = "Köder für stille Flussbarsche", ["text"] = "Wirken in 2 sek.\nReagenzien:\nBlutbarsch (2)\nSpezialisierung:\nAbbauen - Fischereifreund (10)\n\nKöder für stille Flussbarsche\nBenutzen: Erhöht 30 Min. lang die Chance, stille Flussbarsche zu fangen.\n70" }
entries[442646] = { ["name"] = "Köder für dornische Hechte", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKristalliner Stör (2)\nSpezialisierung:\nAbbauen - Fischereifreund (20)\n\nKöder für dornische Hechte\nBenutzen: Erhöht 30 Min. lang die Chance, dornische Hechte zu fangen.\n70" }
entries[442647] = { ["name"] = "Köder für Arathorhammerfische", ["text"] = "Wirken in 2 sek.\nReagenzien:\nBismutbitterling (2)\nSpezialisierung:\nAbbauen - Fischereifreund (30)\n\nKöder für Arathorhammerfische\nBenutzen: Erhöht 30 Min. lang die Chance, Arathorhammerfische zu fangen.\n70" }
entries[442648] = { ["name"] = "Köder für tosende Anglersucher", ["text"] = "Wirken in 2 sek.\nReagenzien:\nTrödelnder Häsling , Blutbarsch , Kristalliner Stör , Bismutbitterling\nSpezialisierung:\nAbbauen - Fischereifreund (40)\n\nKöder für tosende Anglersucher\nBenutzen: Taucht Euren Haken in Anglersucherköder, der einen Fang aus jedem Fischschwarm in den Schallenden Tiefen oder Heilsturz garantiert.\n\nDieser Köder hält 30 Min. lang an und lässt sich bis zu 50-mal stapeln.\n70" }
entries[442649] = { ["name"] = "Infusion: Kristall", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Kristallines Pulver (3)\nSpezialisierung:\nKödern - Inspirierender Infusor\n\nKöder für kristalline Kreaturen\nWird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\nKann nur im Freien in Khaz Algar verwendet werden.\n70\n\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit Kristallpulver angereichert.\"" }
entries[442650] = { ["name"] = "Infusion: Sporen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Grünliche Sporen (3)\nSpezialisierung:\nKödern - Inspirierender Infusor (20)\n\nKöder für sporenverschmolzene Kreaturen\nWird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\nKann nur im Freien in Khaz Algar verwendet werden.\n70\n\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit magischen Sporen angereichert.\"" }
entries[442651] = { ["name"] = "Infusion: Zuckend", ["text"] = "Wirken in 2 sek.\nReagenzien:\nKöder für scheue Kreaturen , Zappelnde Probe\nSpezialisierung:\nKödern - Inspirierender Infusor (40)\n\nKöder für zuckende Kreaturen\nWird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\nKann nur im Freien in Khaz Algar verwendet werden.\n70\n\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken. Mit einer Essenz angereichert, die vor boshafter Energie trieft.\"" }
entries[442652] = { ["name"] = "Köder für scheue Kreaturen", ["text"] = "Wirken in 2 sek.\nReagenzien:\nIm Prinzip Rindfleisch (10)\nSpezialisierung:\nKödern\n\nKöder für scheue Kreaturen\nWird beim Aufheben gebunden\nBenutzen: Platziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\nKann nur im Freien in Khaz Algar verwendet werden.\n70\nBenötigt Kürschnerei von Khaz Algar\n(1)\n\"Ein verlockender Köder, um scheue Kreaturen aus ihrem Versteck zu locken.\"" }
entries[442653] = { ["name"] = "Was ist das denn?", ["text"] = "18 Meter Reichweite\nSofort\nDer Zaubernde entdeckt etwas Seltsames." }
entries[442654] = { ["name"] = "Wildtierlockduft", ["text"] = "Wirken in 2 sek.\nReagenzien:\nIm Prinzip Rindfleisch (3), Gewürzgranulat (5)\nSpezialisierung:\nKödern (20)\n\nWildtierlockduft\nWird beim Aufheben gebunden\nBenutzen: Öffnet die Flasche, um einen Duft freizusetzen, der alle unbeschäftigten häutbaren Wildtiere innerhalb von 60 Metern sofort zu Euch lockt.\n\nKann nur im Freien in Khaz Algar verwendet werden. (5 Min Abklingzeit)\n60\nBenötigt Kürschnerei von Khaz Algar\n(1)" }
entries[442655] = { ["name"] = "Überragender Wildtierköder", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGewürzter Fleischfond\nSpezialisierung:\nKödern - Fähiger Fährtenleser (40)\n\nÜberragender Wildtierköder\nWird beim Aufheben gebunden\nBenutzen: Platziert den Köder und lockt eine hochkarätige scheue Kreatur aus ihrem Versteck.\n\nKann nur in der Grollenden Einöde in den Schallenden Tiefen eingesetzt werden.\n70\nBenötigt Kürschnerei von Khaz Algar\n(1)\n\"Ein exquisiter Köder, der nach detaillierten Vorgaben hergestellt wurde, um ein mächtiges Wildtier anzulocken.\"" }
entries[442656] = { ["name"] = "Sprühender Blutsturz", ["text"] = "100 Meter Reichweite\nSofort\nDer blutgebundene Schrecken erschafft auf jeder Seite zwei Geysire aus Schwarzblut, die sich 20 Sek. lang langsam um sich selbst drehen. Wer in einem Geysir steht, erleidet alle 0.25 Sek. 100 Schattenschaden." }
