entries[442679] = { ["name"] = "Mal des Reißers", ["text"] = "Verwüstung\nWenn 'Chaosstoß' durch 'Gleve des Reißers' verstärkt wird, wird 'Mal des Reißers' angewandt, wodurch das Ziel 20 Sek. lang 7% mehr Schaden erleidet. Bis zu 2-mal stapelbar.\n\nGewährt 1 zusätzlichen Stapel von 'Mal des Reißers', wenn es nach 'Klingentanz' eingesetzt wird.\n\nRachsucht\nWenn durch 'Gleve des Reißers' verstärkt wird, wird 'Mal des Reißers' angewandt, wodurch das Ziel 20 Sek. lang 7% mehr Schaden erleidet. Bis zu 2-mal stapelbar.\n\nGewährt 1 zusätzlichen Stapel von 'Mal des Reißers', wenn es nach 'Seelenspalter' eingesetzt wird." }
entries[442680] = { ["name"] = "Köder für scheue Kreaturen", ["text"] = "2 Meter ReichweiteWirken in 2 sek. 12 std. Abklingzeit\nPlatziert den Köder, was nach kurzer Zeit eine scheue Kreatur anlockt. Wer weiß, was sich blicken lässt?\n\nDie Abklingzeit des Köders für scheue Kreaturen wird beim Kürschnern von Kreaturen in Khaz Algar verringert.\n\nKann nur im Freien in Khaz Algar verwendet werden." }
