entries[442799] = { ["name"] = "Blutiger Überschuss", ["text"] = "300 Meter Reichweite\nSofort\nSchwarzblut ergießt sich aus Kanistern über den Boden der Kammer und breitet sich langsam aus. Die Lache verursacht alle 0.5 Sek. 287816 Schattenschaden und absorbiert die nächsten 490734 von Spielercharakteren innerhalb des Effektbereichs erhaltene Heilung.\n\nExperimentelle Eier, die in Kontakt mit der Lache kommen, lösen eine ' Ätzende Reaktion ' aus." }
entries[442801] = { ["name"] = "Lauffeuerdocht", ["text"] = "50 Meter Reichweite\nSofort\nEure Nahkampfangriffe haben eine Chance, das Ziel in Brand zu stecken und ihm so ( 53 * 11) Feuerschaden im Verlauf von 11 Sek. zuzufügen.\n\nWenn dieser Effekt ausgelöst wird, während das Ziel bereits brennt, wird seine Dauer erneuert und er breitet sich auf einen Gegner in der Nähe aus." }
entries[442802] = { ["name"] = "Blutiger Überschuss", ["text"] = "300 Meter Reichweite\nSofort\n' Blutiger Überschuss ' bringt vom Effekt berührte Eier zum Schlüpfen und lässt die Kreaturen darin mutieren." }
entries[442804] = { ["name"] = "Fluch der Satyrn", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nErhöht die Zeit zwischen Angriffen eines Gegners 2 Min. lang um 20% und die Zauberzeit aller Zauber um 30%.\n\nFlüche: Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
